<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<!-- <ul>			<a href="{pigcms{:U('Recruit/company_list')}" class="on">企业列表</a>		</ul> -->	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/company_list')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="company_list"/>					<if condition="$admin_area neq 3">						<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>					</if>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="company_name" <if condition="$_GET['type'] eq 'company_name'">selected="selected"</if>>企业名称</option>                        <option value="name" <if condition="$_GET['type'] eq 'name'">selected="selected"</if>>用户昵称</option>                    </select>                    <input type="submit" value="查询" class="button"/>                    &nbsp;&nbsp;                    <input type="button" value="添加企业" class="button" onclick="window.top.artiframe('{pigcms{:U('company_edit')}','添加企业',800,480,true,false,false,addbtn,'add',true);"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<colgroup>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col  align="center"/>				</colgroup>				<thead>					<tr>						<th>编号</th>						<th>企业名称</th>						<th>法人姓名</th>						<th>手机号</th>						<th>身份证号</th>						<th>地址</th>						<th>店铺面积</th>						<th>状态</th>						<th>是否隐藏</th>						<th>申请时间</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list['list']">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.company_id}</td>								<td>{pigcms{$vo.company_name}</td>								<td>{pigcms{$vo.legal_person_name}</td>								<td>{pigcms{$vo.phone}</td>								<td>{pigcms{$vo.ID_number}</td>								<td>{pigcms{$vo.address}</td>								<td>{pigcms{$vo.acreage}</td>								<td>                                <if condition="$vo['status'] eq 0">                                	<span style="color: orange;">待审核</span>                                <elseif condition="$vo['status'] eq 1"/>                                	<span style="color: green;">审核通过</span>                                <elseif condition="$vo['status'] eq 2"/>                                	<span style="color: red;">审核不通过</span>                                </if>                            	</td>								<td>                                <if condition="$vo['is_hide'] eq 0">                                	<span>否</span>                                <elseif condition="$vo['is_hide'] eq 1"/>                                	<span style="color: red;">是</span>                                </if>                            	</td>                                <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>								<td>									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('company_edit',array('id'=>$vo['company_id']))}','编辑','60%','60%',true,false,false,editbtn,'edit',true);">编辑</a>|									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('company_audit',array('company_id'=>$vo['company_id']))}','审核',600,500,true,false,false,editbtn,'edit',true);">审核</a>|									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.company_id}" url="{pigcms{:U('company_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="20">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="20">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>